const lessons5=[{n:3,g:5,method:'add',name:'첫 단서 · 한 묶음 더하기',guided:true},{n:6,g:7,method:'add',name:'빠진 간식 봉지 찾기',guided:true},{n:4,g:6,method:'add',name:'그림 없이 식으로 찾아보기'},{n:6,g:7,method:'add',name:'잠시 뒤 다시 떠올리기',recall:true},{n:5,g:4,method:'sub',name:'새 방법 · 한 묶음 빼기',guided:true},{n:8,g:3,method:'double',name:'새 방법 · 같은 배열 두 배 하기',guided:true},{n:3,g:7,method:'add',name:'구구단 탐정 · 확인 1',test:true},{n:5,g:6,method:'sub',name:'구구단 탐정 · 확인 2',test:true},{n:6,g:3,method:'double',name:'구구단 탐정 · 확인 3',test:true}];
let s5={done:false,cards:[]};const d5=()=>lessons5[s5.i];
function base5(){const d=d5();return d.method==='double'?{n:d.n/2,g:d.g,total:d.n/2*d.g}:{n:d.n,g:d.g+(d.method==='add'?-1:1),total:d.n*(d.g+(d.method==='add'?-1:1))}}
function start5(){s5={done:s5.done,cards:s5.cards||[],i:0,score:0};init5()}
function init5(){Object.assign(s5,{phase:'challenge',route:'바로 떠올림',picture:false,changed:false,fill:0,clue:false,recorded:false,retry:false,msg:d5().guided?'새 방법을 함께 배워요. 아는 식 찾기를 눌러 시작하세요.':'바로 떠오르면 답해도 좋아요. 막히면 아는 식을 찾아요.'});render5()}
function clue5(){s5.phase='clue';if(s5.route!=='그림을 보고 해결')s5.route='아는 식으로 해결';s5.msg='오늘의 방법으로 바로 바꿀 수 있는 식을 골라요.';render5()}
function selectClue5(ok){if(!ok){s5.msg='이번에는 '+(d5().method==='double'?'한 줄의 개수가 절반이고 줄 수가 같은 배열':d5().method==='add'?'한 묶음 적은 식':'한 묶음 많은 식')+'을 찾아봐요.';render5();return}s5.clue=true;s5.phase='transform';s5.picture=!!d5().guided;if(s5.picture)s5.route='그림을 보고 해결';s5.msg='아는 식에서 무엇을 바꾸면 될까요?';render5()}
function picture5(){s5.picture=true;s5.route='그림을 보고 해결';s5.msg='묶음을 바꾸며 식이 어떻게 달라지는지 살펴봐요.';render5()}
function change5(){s5.changed=true;s5.msg=d5().method==='sub'?'한 묶음을 꺼냈어요. 한 묶음 안의 개수만큼 빼요.':d5().method==='double'?'같은 배열을 옆에 붙였어요. 각 줄의 개수가 두 배가 되었어요.':'새 봉지에 한 묶음의 개수만큼 담았어요.';render5()}
function fill5(delta){s5.fill=Math.max(0,Math.min(d5().n+2,s5.fill+delta));render5()}
function confirmFill5(){if(s5.fill!==d5().n){s5.msg=`새 봉지 하나에도 ${d5().n}개씩 담아야 해요. 지금 담은 개수를 확인해요.`;render5();return}change5()}
function calc5(){if(!s5.changed)return;s5.phase='calc';s5.msg='바뀐 개수만큼 계산한 뒤 도전 식을 완성해요.';render5()}
function submit5(value){const d=d5();if(!Number.isInteger(value)||value<0){s5.msg='답을 숫자로 써 주세요.';render5();return}if(value!==d.n*d.g){s5.retry=true;s5.msg=s5.phase==='challenge'?'아는 식 찾기를 눌러, 가까운 식에서 다시 생각해 봐요.':d.method==='add'?`${base5().total}에서 새 봉지 하나만큼 늘었어요. 새 봉지에는 몇 개씩 있나요?`:d.method==='sub'?`${base5().total}에서 한 묶음을 꺼냈어요. 몇 개가 줄었나요?`:`같은 배열의 답 ${base5().total}을 한 번 더 더해 봐요.`;render5();return}if(s5.phase==='challenge'&&(d.guided||d.test)){s5.msg='답을 떠올렸네요! 이번에는 아는 식을 골라 어떻게 찾는지도 확인해요.';clue5();return}s5.phase=s5.clue?'explain':'done';if(s5.phase==='done'){saveCard5();s5.msg='단서 없이 답을 떠올렸어요!'}else{s5.msg='답을 찾았어요! 그림에 무엇을 바꾸었는지 골라요.'}render5()}
function explain5(ok){if(!ok){s5.msg='선택한 방법을 다시 떠올려요. '+(d5().method==='add'?'봉지가 하나 늘었어요.':d5().method==='sub'?'봉지가 하나 줄었어요.':'같은 배열을 옆에 하나 더 붙였어요.');render5();return}s5.phase='done';if(d5().test)s5.score++;saveCard5();s5.msg='아는 식을 단서로 답을 찾았어요. 힌트를 써도 멋진 해결이에요!';render5()}
function saveCard5(){if(s5.recorded)return;const d=d5(),key=`${d.n} × ${d.g}`;let card=s5.cards.find(c=>c.key===key);if(!card){card={key,answer:d.n*d.g,history:[]};s5.cards.push(card)}card.history.push(s5.route);card.route=s5.route;s5.recorded=true}
function next5(){if(s5.phase!=='done')return;s5.i++;if(s5.i===lessons5.length){finish5();return}init5();document.querySelector('#app').scrollIntoView?.({block:'start'})}
function illustration5(){const d=d5(),b=base5();if(d.method==='double'){return `<div class="double-array" role="img" aria-label="${b.n}개씩 ${b.g}줄인 배열${s5.changed?' 두 개를 옆으로 붙임':''}">${Array.from({length:d.g},()=>`<div class="double-row"><span>${Array(b.n).fill('●').join(' ')}</span>${s5.changed?`<span class="added-half">${Array(b.n).fill('●').join(' ')}</span>`:''}</div>`).join('')}</div><p class="small">한 줄에 ${s5.changed?d.n:b.n}개씩, ${d.g}줄이에요.</p>`}const count=d.method==='sub'?b.g:b.g;return `<div class="group-grid">${Array.from({length:count},(_,i)=>`<div class="group-box ${d.method==='sub'&&s5.changed&&i===count-1?'removed':''}"><small>${i+1}봉지${d.method==='sub'&&s5.changed&&i===count-1?' · 꺼냈어요':''}</small>${Array(d.n).fill('●').join(' ')}</div>`).join('')}${d.method==='add'?`<div class="group-box new"><small>새 봉지 · ${s5.changed?d.n:s5.fill}개</small>${Array(s5.changed?d.n:s5.fill).fill('●').join(' ')||'비어 있어요'}${!s5.changed?'<div class="controls"><button onclick="fill5(-1)" aria-label="하나 꺼내기">−</button><button onclick="fill5(1)" aria-label="하나 담기">+</button></div>':''}</div>`:''}</div>`}
function render5(){view='stage5';const d=d5(),b=base5(),p=s5.phase,op=d.method==='sub'?'−':'+',term=d.method==='double'?b.total:d.n;let body='';if(p==='clue'){body=`<h2>내가 아는 단서</h2><p>${d.method==='add'?'한 묶음 더하기':d.method==='sub'?'한 묶음 빼기':'두 배 하기'}로 이어지는 식을 골라요.</p><div class="choices">${(s5.i%2?[[d.n,d.g+2,false],[b.n,b.g,true]]:[[b.n,b.g,true],[d.n,d.g+2,false]]).map(([n,g,ok])=>`<button onclick="selectClue5(${ok})">${n} × ${g} = ${n*g}</button>`).join('')}</div>`}if(['transform','calc','explain','done'].includes(p)&&s5.clue)body+=`<div class="clue-strip">내가 고른 식 <b>${b.n} × ${b.g} = ${b.total}</b></div>`;if(s5.picture&&p!=='done')body+=illustration5();if(p==='transform'){body+=s5.changed?`<div class="equation">${b.total} ${op} ${term} = □</div><button class="primary" onclick="calc5()">답 완성하기 →</button>`:s5.picture&&d.method==='add'?'<button class="primary" onclick="confirmFill5()">새 봉지를 다 채웠어요</button>':`<button class="primary" onclick="change5()">${d.method==='add'?`${d.n}개짜리 한 묶음 붙이기`:d.method==='sub'?`${d.n}개짜리 한 묶음 꺼내기`:'같은 배열을 옆에 하나 더 붙이기'}</button>`;if(!s5.picture)body+='<button onclick="picture5()">그림 단서 보기</button>'}if(p==='calc')body+=`<div class="equation">${b.total} ${op} ${term} = □</div>`;if(p==='challenge'||p==='calc'){body+=`<form id="answerForm5"><label for="answerInput5">${d.n} × ${d.g}의 답</label><div class="answer-entry"><input id="answerInput5" name="answer" type="number" inputmode="numeric" min="0" max="99" required autocomplete="off"><button class="primary" type="submit">답 확인</button></div></form>${p==='challenge'?'<button onclick="clue5()">아는 식 찾기</button>':!s5.picture?'<button onclick="picture5()">그림 단서 보기</button>':''}`}if(p==='explain'){const correct=d.method==='add'?`${d.n}개짜리 한 묶음을 더했어요`:d.method==='sub'?`${d.n}개짜리 한 묶음을 뺐어요`:`${b.n}개씩 ${b.g}줄인 배열을 옆에 하나 더 붙였어요`;body+=`<div class="equation">${b.total} ${op} ${term} = ${d.n*d.g}</div><h2>무엇을 바꾸었나요?</h2><div class="choices"><button onclick="explain5(false)">점 한 개만 더했어요</button><button onclick="explain5(true)">${correct}</button></div>`}if(p==='done')body+=`<p class="pill">${s5.route}</p><p>이 식을 내 카드에 모았어요.</p>`;app.innerHTML=`<div class="topline"><span class="pill">5단계 · 아는 답으로 새 답 찾기</span><span class="small">활동 ${s5.i+1} / 9</span></div><section class="activity"><span class="small">${d.name}</span><h1 class="instruction">구구단 탐정</h1><div class="equation">${d.n} × ${d.g} = ${p==='done'||p==='explain'?d.n*d.g:'□'}</div><div class="workspace">${body}</div><div class="feedback ${p==='done'?'good':''}" role="status">${s5.msg}</div><div class="actions"><button onclick="home()">전체 단계</button>${p==='done'?'<button class="primary" onclick="next5()">다음 활동 →</button>':''}</div></section>`;const form=document.querySelector('#answerForm5');if(form)form.onsubmit=e=>{e.preventDefault();const raw=document.querySelector('#answerInput5').value;submit5(raw.trim()===''?NaN:Number(raw))}}
function finish5(){s5.done=s5.score>=2;view='stage5';app.innerHTML=`<section class="activity"><span class="pill">5단계 마무리</span><h1>${s5.done?'아는 식으로 새 답을 찾았어요!':'내가 찾은 답을 모았어요!'}</h1><p>확인 문제 3개 중 ${s5.score}개에서 아는 식을 고르고, 바꾼 방법을 설명했어요.<br>힌트를 이용해 해결한 문제도 성공이에요.</p><h2>내가 해결한 식 카드</h2><p class="small">카드를 누르면 답을 가리거나 볼 수 있어요. 먼저 떠올리고 확인해 보세요.<br>카드와 기록은 이 브라우저에 저장되어 다음에도 볼 수 있어요.</p><div class="saved-cards">${s5.cards.map((c,i)=>`<article><button class="recall-card" onclick="flipCard5(${i},this)" aria-label="${c.key} 답 보기" aria-pressed="false">${c.key} = ?</button><p>${c.route}</p>${c.history.length>1?`<small>처음: ${c.history[0]}<br>최근: ${c.route}</small>`:''}</article>`).join('')}</div><p>6단계에서는 카드를 가리고 먼저 떠올린 뒤, 막히는 식을 다시 연습해요.</p><p class="small">6단계에서 이 카드들을 다시 떠올려 보세요.</p><div class="actions"><button class="primary" onclick="start6()">6단계 카드함 열기</button><button onclick="start5()">5단계 다시 하기</button><button class="primary" onclick="home()">전체 단계 보기</button></div></section>`}
function flipCard5(i,button){const c=s5.cards[i],open=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(open));button.setAttribute('aria-label',c.key+(open?' 답 가리기':' 답 보기'));button.textContent=`${c.key} = ${open?c.answer:'?'}`}
